import sys, json, urllib.request
tok = sys.argv[1]
def post(path, payload):
  req = urllib.request.Request(
    f"https://src.opensuse.org/api/v1{path}",
    data=json.dumps(payload).encode(),
    headers={"Authorization": f"token {tok}", "Content-Type": "application/json"},
    method="POST")
  try:
    r = urllib.request.urlopen(req)
    d = json.loads(r.read())
    return ("OK", d.get("number"), d.get("html_url"), d.get("mergeable"))
  except Exception as e:
    return ("ERR", e.read().decode()[:400] if hasattr(e, 'read') else str(e), None, None)
for base in ("leap-16.0", "leap-16.1"):
  body = "Sync %s with the devel 1.50.0 sources." % base
  st, num, url, mg = post("/repos/pool/goose/pulls", {
    "head": "someone:leap-sync-1.50.0", "base": base,
    "title": f"Update to 1.50.0 (sync {base} with Factory)", "body": body})
  print(base, "->", st, num, url, "mergeable:", mg)
EOF

